<?php
declare(strict_types=1);
session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)($_SESSION['role']??'');$reviewRoles=['head_academic','headteacher','sub_director','director'];
if(!in_array($role,array_merge(['teacher'],$reviewRoles),true)){http_response_code(403);exit('Your role cannot manage homework.');}
$uid=(int)$_SESSION['user_id'];$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$ids=array_map('intval',array_column($schools,'id'));$requested=(int)($_GET['school_id']??($ids[0]??0));$school=in_array($requested,$ids,true)?$requested:0;$csrf=csrf_token();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Homework · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/homework.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Teaching <span>/</span> Homework</div></header><div class="page-content" data-homework-page data-api="api/homework.php" data-school="<?=$school?>" data-csrf="<?=e($csrf)?>" data-role="<?=e($role)?>"><section class="welcome-row"><div><div class="eyebrow">LEARNER ACTIVITIES</div><h1>Homework and activities</h1><p class="muted">Assign work, follow submissions and provide feedback.</p></div><?php if(count($schools)>1):?><form method="get"><label for="homework-school">School</label><select id="homework-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><?php if(!$school):?><div class="empty-state"><h2>No school is linked</h2><p>Ask an administrator to link your account.</p></div><?php else:?><div data-homework-status class="notice" role="status" aria-live="polite" hidden></div><?php if($role==='teacher'):?><section class="note-create"><div class="section-heading"><h2>Create homework</h2></div><form data-homework-form class="note-form"><input type="hidden" name="action" value="save_assignment"><div class="form-grid"><div><label for="hw-class">Class</label><select id="hw-class" name="class_id" required></select></div><div><label for="hw-subject">Subject</label><select id="hw-subject" name="subject_id" required></select></div><div><label for="hw-title">Title</label><input id="hw-title" name="title" maxlength="180" required></div><div><label for="hw-due">Due date</label><input id="hw-due" name="due_date" type="date"></div><div><label for="hw-material">Learning material (optional)</label><select id="hw-material" name="learning_note_id"><option value="">No linked material</option></select></div><div class="question-wide"><label for="hw-instructions">Instructions</label><textarea id="hw-instructions" name="instructions" rows="5" maxlength="12000" required></textarea></div></div><div class="planning-actions"><button class="button" name="status" value="draft">Save draft</button><button class="button primary" name="status" value="published">Publish to class</button></div></form></section><?php endif;?><section class="content-section"><div class="section-heading"><h2>Assignments</h2><button type="button" class="button" data-homework-refresh>Refresh</button></div><div class="table-wrap" data-homework-list><p class="muted">Loading homework…</p></div></section><section class="content-section" data-submission-section hidden><h2>Submissions</h2><div data-homework-submissions></div></section><?php endif;?><footer class="page-footer">ShuleLite · Homework</footer></div></main></div></div><dialog id="homework-review-dialog" class="subject-dialog"><form method="dialog"><div class="subject-dialog-head"><h2>Review response</h2><button class="icon-button" value="cancel" aria-label="Close">×</button></div><div class="subject-dialog-body"><input type="hidden" name="submission_id"><label for="hw-feedback">Feedback</label><textarea id="hw-feedback" name="feedback" rows="4" maxlength="4000" required></textarea><div class="planning-actions"><button class="button primary" type="button" data-homework-review>Save feedback</button><button class="button" value="cancel">Cancel</button></div></div></form></dialog></body></html>
